import { createBrowserRouter } from 'react-router';
import App from './App';
import Auth0Provider from './auth/Auth0Provider';
import AuthGuard from './auth/AuthGuard';
import { ErrorProvider, ErrorSnackbar } from './error';
import ProfilePage from './pages/ProfilePage';

const router = createBrowserRouter([
  {
    path: '/',
    // Auth0Provider must live inside the Router so its `onRedirectCallback`
    // can use `useNavigate` (react-router throws outside Router context).
    element: (
      <Auth0Provider>
        <ErrorProvider>
          <App />
          <ErrorSnackbar />
        </ErrorProvider>
      </Auth0Provider>
    ),
    children: [
      {
        index: true,
        element: (
          <AuthGuard>
            <div>Dashboard</div>
          </AuthGuard>
        ),
      },
      {
        path: 'collections',
        element: (
          <AuthGuard>
            <div>Collections</div>
          </AuthGuard>
        ),
      },
      {
        path: 'bookmarks',
        element: (
          <AuthGuard>
            <div>Bookmarks</div>
          </AuthGuard>
        ),
      },
      {
        path: 'all',
        element: (
          <AuthGuard>
            <div>All</div>
          </AuthGuard>
        ),
      },
      { path: 'profile', element: <ProfilePage /> },
      // Auth0 redirects back to /callback after login — the SDK processes
      // the code exchange automatically when the component tree mounts.
      { path: 'callback', element: null },
    ],
  },
]);

export default router;

import { env } from '../env';

export interface MeResponse {
  sub: string;
}

/**
 * Calls GET /me with a Bearer token.
 * Returns the authenticated user profile from the backend.
 */
export async function fetchMe(accessToken: string): Promise<MeResponse> {
  const response = await fetch(`${env.VITE_API_URL}/me`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });

  if (!response.ok) {
    throw new Error(`/me returned ${response.status}`);
  }

  return response.json() as Promise<MeResponse>;
}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { AppController } from './app.controller';
import { PrismaModule } from './prisma/prisma.module';
import { AuthModule } from './auth/auth.module';
import { UsersModule } from './users/users.module';

@Module({
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
      envFilePath: '.env',
    }),
    PrismaModule,
    AuthModule,
    UsersModule,
  ],
  controllers: [AppController],
})
export class AppModule {}

import {
  Box,
  Card,
  CardActionArea,
  CardContent,
  IconButton,
  Typography,
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import type { Collection } from '../../api/collections';

interface CollectionCardProps {
  collection: Collection;
  onEdit: () => void;
  onDelete: () => void;
  onClick: () => void;
}

export default function CollectionCard({
  collection,
  onEdit,
  onDelete,
  onClick,
}: CollectionCardProps) {
  const bookmarkCount = collection._count?.bookmarks ?? 0;

  return (
    <Card variant="outlined">
      <CardActionArea onClick={onClick}>
        <CardContent
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <Box>
            <Typography variant="h6">{collection.name}</Typography>
            <Typography variant="body2" color="text.secondary">
              {bookmarkCount === 1
                ? '1 bookmark'
                : `${bookmarkCount} bookmarks`}
            </Typography>
          </Box>
          <Box sx={{ display: 'flex', gap: 1 }}>
            <IconButton
              aria-label="Edit collection"
              size="small"
              onClick={(e) => {
                e.stopPropagation();
                onEdit();
              }}
            >
              <EditIcon fontSize="small" />
            </IconButton>
            <IconButton
              aria-label="Delete collection"
              size="small"
              color="error"
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Box>
        </CardContent>
      </CardActionArea>
    </Card>
  );
}

import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
} from '@mui/material';
import { useCallback, useState } from 'react';

interface CreateModeProps {
  open: boolean;
  onClose: () => void;
  onCreate: (name: string) => Promise<void>;
  onSave?: never;
  collection?: never;
}

interface EditModeProps {
  open: boolean;
  onClose: () => void;
  onSave: (id: string, name: string) => Promise<void>;
  collection: { id: string; name: string };
  onCreate?: never;
}

type CollectionDialogProps = CreateModeProps | EditModeProps;

export default function CollectionDialog(props: CollectionDialogProps) {
  const { open, onClose } = props;
  const isEditMode = 'collection' in props && props.collection !== undefined;

  const initialName = isEditMode ? props.collection.name : '';
  const [name, setName] = useState(initialName);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Reset form when dialog opens
  const handleEntered = useCallback(() => {
    setName(initialName);
    setIsSubmitting(false);
  }, [initialName]);

  const isNameValid = name.trim().length > 0;
  const isNameChanged = name.trim() !== initialName.trim();
  const isPrimaryDisabled = !isNameValid || (isEditMode && !isNameChanged) || isSubmitting;

  const handleSubmit = useCallback(async () => {
    if (isPrimaryDisabled) return;

    setIsSubmitting(true);
    try {
      if (isEditMode) {
        await props.onSave(props.collection.id, name.trim());
      } else {
        await props.onCreate(name.trim());
      }
      onClose();
    } catch {
      // Error is surfaced via useError() in the parent — keep dialog open
      setIsSubmitting(false);
    }
  }, [isPrimaryDisabled, name, isEditMode, props, onClose]);

  return (
    <Dialog
      open={open}
      onClose={isSubmitting ? undefined : onClose}
      maxWidth="xs"
      fullWidth
      slotProps={{
        paper: {
          sx: { borderRadius: 'var(--radius-lg)' },
        },
        transition: {
          onEntered: handleEntered,
        },
      }}
    >
      <DialogTitle>
        {isEditMode ? 'Edit Collection' : 'New Collection'}
      </DialogTitle>
      <DialogContent>
        <TextField
          autoFocus
          fullWidth
          label="Collection name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          disabled={isSubmitting}
          slotProps={{
            htmlInput: {
              onKeyDown: (e: React.KeyboardEvent) => {
                if (e.key === 'Enter' && !isPrimaryDisabled) {
                  handleSubmit();
                }
              },
            },
          }}
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={isSubmitting}>
          Cancel
        </Button>
        <Button
          variant="contained"
          onClick={handleSubmit}
          disabled={isPrimaryDisabled}
        >
          {isEditMode ? 'Save' : 'Create'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from '@mui/material';
import { useCallback, useState } from 'react';

interface DeleteCollectionDialogProps {
  open: boolean;
  collectionName: string;
  onClose: () => void;
  onDelete: () => Promise<void>;
}

export default function DeleteCollectionDialog({
  open,
  collectionName,
  onClose,
  onDelete,
}: DeleteCollectionDialogProps) {
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDelete();
      onClose();
    } catch {
      // Error is surfaced via useError() in the parent — keep dialog open
      setIsDeleting(false);
    }
  }, [onDelete, onClose]);

  return (
    <Dialog
      open={open}
      onClose={isDeleting ? undefined : onClose}
      maxWidth="xs"
      fullWidth
      slotProps={{
        paper: {
          sx: { borderRadius: 'var(--radius-lg)' },
        },
        transition: {
          onEntered: () => setIsDeleting(false),
        },
      }}
    >
      <DialogTitle>Delete collection?</DialogTitle>
      <DialogContent>
        <DialogContentText>
          This will delete the collection &apos;{collectionName}&apos;.
          Bookmarks in this collection will become uncategorized.
        </DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={isDeleting}>
          Cancel
        </Button>
        <Button
          variant="contained"
          color="error"
          onClick={handleDelete}
          disabled={isDeleting}
        >
          Delete
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Box,
  Button,
  FormControl,
  InputLabel,
  Select,
  Skeleton,
  TextField,
  Typography,
  type SelectChangeEvent,
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import FolderOpenIcon from '@mui/icons-material/FolderOpen';
import MenuItem from '@mui/material/MenuItem';
import AddIcon from '@mui/icons-material/Add';
import { useAuth0 } from '@auth0/auth0-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router';
import AuthGuard from '../auth/AuthGuard';
import { useError } from '../error/useError';
import {
  createCollection,
  deleteCollection,
  fetchCollections,
  updateCollection,
  type Collection,
} from '../api/collections';
import CollectionList from '../components/collections/CollectionList';
import CollectionDialog from '../components/collections/CollectionDialog';
import DeleteCollectionDialog from '../components/collections/DeleteCollectionDialog';

type SortOption = 'newest' | 'oldest' | 'a-z' | 'z-a';

function sortOptionToParams(
  option: SortOption,
): { sortBy: 'name' | 'createdAt' | 'updatedAt'; sortOrder: 'asc' | 'desc' } {
  switch (option) {
    case 'newest':
      return { sortBy: 'createdAt', sortOrder: 'desc' };
    case 'oldest':
      return { sortBy: 'createdAt', sortOrder: 'asc' };
    case 'a-z':
      return { sortBy: 'name', sortOrder: 'asc' };
    case 'z-a':
      return { sortBy: 'name', sortOrder: 'desc' };
  }
}

function CollectionsContent() {
  const { getAccessTokenSilently } = useAuth0();
  const { showError } = useError();
  const navigate = useNavigate();

  const [collections, setCollections] = useState<Collection[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState<SortOption>('newest');

  // Dialog state
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editingCollection, setEditingCollection] =
    useState<Collection | null>(null);
  const [deletingCollection, setDeletingCollection] =
    useState<Collection | null>(null);

  // Debounce ref
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(null);
  // Track whether initial load has happened
  const hasLoadedRef = useRef(false);

  const sortParams = useMemo(() => sortOptionToParams(sort), [sort]);

  const loadCollections = useCallback(
    async (name?: string) => {
      setIsLoading(true);
      try {
        const token = await getAccessTokenSilently();
        const params = { ...sortParams, ...(name ? { name } : {}) };
        const data = await fetchCollections(token, params);
        setCollections(data);
      } catch {
        showError('Failed to load collections. Please try again.');
      } finally {
        setIsLoading(false);
      }
    },
    [getAccessTokenSilently, showError, sortParams],
  );

  // Reload when sort changes (skip initial mount)
  useEffect(() => {
    if (!hasLoadedRef.current) {
      hasLoadedRef.current = true;
      return;
    }
    loadCollections(search || undefined);
  }, [sort]); // eslint-disable-line react-hooks/exhaustive-deps

  // Initial load — only on mount
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- intentional: data fetch on mount
    loadCollections();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Debounced search
  useEffect(() => {
    if (!hasLoadedRef.current) return;

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    debounceRef.current = setTimeout(() => {
      loadCollections(search || undefined);
    }, 300);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [search]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = useCallback(
    async (name: string) => {
      try {
        const token = await getAccessTokenSilently();
        await createCollection(token, name);
        await loadCollections(search || undefined);
      } catch {
        showError('Failed to create collection. Please try again.');
      }
    },
    [getAccessTokenSilently, loadCollections, search, showError],
  );

  const handleUpdate = useCallback(
    async (id: string, name: string) => {
      try {
        const token = await getAccessTokenSilently();
        await updateCollection(token, id, name);
        await loadCollections(search || undefined);
      } catch {
        showError('Failed to update collection. Please try again.');
      }
    },
    [getAccessTokenSilently, loadCollections, search, showError],
  );

  const handleDelete = useCallback(async () => {
    if (!deletingCollection) return;
    try {
      const token = await getAccessTokenSilently();
      await deleteCollection(token, deletingCollection.id);
      // Optimistic: remove from list
      setCollections((prev) =>
        prev.filter((c) => c.id !== deletingCollection.id),
      );
    } catch {
      showError('Failed to delete collection. Please try again.');
      // Refresh list to restore if optimistic removal failed
      await loadCollections(search || undefined);
    }
  }, [
    getAccessTokenSilently,
    deletingCollection,
    loadCollections,
    search,
    showError,
  ]);

  const handleSortChange = useCallback((e: SelectChangeEvent) => {
    setSort(e.target.value as SortOption);
  }, []);

  const isEmpty = !isLoading && collections.length === 0 && !search;

  return (
    <Box sx={{ maxWidth: 560, mx: 'auto' }}>
      <Typography variant="h4" component="h1" sx={{ mb: 3 }}>
        Collections
      </Typography>

      <Box
        sx={{
          display: 'flex',
          gap: 1.5,
          mb: 3,
          flexWrap: 'wrap',
        }}
      >
        <TextField
          placeholder="Search collections…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          size="small"
          slotProps={{
            input: {
              startAdornment: (
                <SearchIcon fontSize="small" color="action" />
              ),
            },
          }}
          sx={{ flex: 1, minWidth: 200 }}
        />

        <FormControl size="small" sx={{ minWidth: 120 }}>
          <InputLabel id="sort-label">Sort</InputLabel>
          <Select
            labelId="sort-label"
            label="Sort"
            value={sort}
            onChange={handleSortChange}
          >
            <MenuItem value="newest">Newest</MenuItem>
            <MenuItem value="oldest">Oldest</MenuItem>
            <MenuItem value="a-z">A–Z</MenuItem>
            <MenuItem value="z-a">Z–A</MenuItem>
          </Select>
        </FormControl>

        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setCreateDialogOpen(true)}
        >
          New Collection
        </Button>
      </Box>

      {isLoading ? (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
          {[1, 2, 3].map((i) => (
            <Skeleton
              key={i}
              variant="rounded"
              height={72}
              sx={{ borderRadius: 'var(--radius-md)' }}
            />
          ))}
        </Box>
      ) : isEmpty ? (
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 1.5,
            py: 8,
          }}
        >
          <FolderOpenIcon sx={{ fontSize: 64, color: 'text.secondary' }} />
          <Typography variant="h6" color="text.secondary">
            No collections yet
          </Typography>
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ textAlign: 'center' }}
          >
            Create your first collection to start organizing your bookmarks.
          </Typography>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setCreateDialogOpen(true)}
          >
            Create your first collection
          </Button>
        </Box>
      ) : (
        <CollectionList
          collections={collections}
          onEdit={setEditingCollection}
          onDelete={setDeletingCollection}
          onClick={(collection) => navigate(`/collections/${collection.id}`)}
        />
      )}

      {/* Create dialog */}
      <CollectionDialog
        open={createDialogOpen}
        onClose={() => setCreateDialogOpen(false)}
        onCreate={handleCreate}
      />

      {/* Edit dialog */}
      {editingCollection && (
        <CollectionDialog
          open={true}
          onClose={() => setEditingCollection(null)}
          onSave={handleUpdate}
          collection={{
            id: editingCollection.id,
            name: editingCollection.name,
          }}
        />
      )}

      {/* Delete confirmation dialog */}
      {deletingCollection && (
        <DeleteCollectionDialog
          open={true}
          collectionName={deletingCollection.name}
          onClose={() => setDeletingCollection(null)}
          onDelete={handleDelete}
        />
      )}
    </Box>
  );
}

export default function CollectionsPage() {
  return (
    <AuthGuard>
      <CollectionsContent />
    </AuthGuard>
  );
}

import {
  Box,
  Card,
  CardContent,
  Skeleton,
  Typography,
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import Button from '@mui/material/Button';
import { useAuth0 } from '@auth0/auth0-react';
import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router';
import AuthGuard from '../auth/AuthGuard';
import { useError } from '../error/useError';
import { fetchCollection, type Collection } from '../api/collections';

function CollectionDetailContent() {
  const { id } = useParams<{ id: string }>();
  const { getAccessTokenSilently } = useAuth0();
  const { showError } = useError();
  const [collection, setCollection] = useState<Collection | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (!id) return;

    getAccessTokenSilently()
      .then((token) => fetchCollection(token, id))
      .then((data) => setCollection(data))
      .catch(() => {
        showError('Failed to load collection. Please try again.');
      })
      .finally(() => setIsLoading(false));
  }, [id, getAccessTokenSilently, showError]);

  const bookmarkCount = collection?._count?.bookmarks ?? 0;
  const createdAt = collection
    ? new Date(collection.createdAt).toLocaleDateString()
    : '';
  const updatedAt = collection
    ? new Date(collection.updatedAt).toLocaleDateString()
    : '';

  return (
    <Box sx={{ maxWidth: 560, mx: 'auto' }}>
      <Button
        component={Link}
        to="/collections"
        startIcon={<ArrowBackIcon />}
        sx={{ mb: 2 }}
      >
        Back to Collections
      </Button>

      {isLoading ? (
        <Card variant="outlined">
          <CardContent sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            <Skeleton variant="text" width="60%" height={40} />
            <Skeleton variant="text" width="30%" />
            <Skeleton variant="text" width="40%" />
            <Skeleton variant="text" width="40%" />
          </CardContent>
        </Card>
      ) : collection ? (
        <>
          <Typography variant="h4" component="h1" sx={{ mb: 3 }}>
            {collection.name}
          </Typography>

          <Card variant="outlined">
            <CardContent
              sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}
            >
              <Typography variant="body1" color="text.secondary">
                {bookmarkCount === 1
                  ? '1 bookmark'
                  : `${bookmarkCount} bookmarks`}
              </Typography>

              <Box>
                <Typography variant="body2" color="text.secondary">
                  Created
                </Typography>
                <Typography variant="body1">{createdAt}</Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="text.secondary">
                  Last updated
                </Typography>
                <Typography variant="body1">{updatedAt}</Typography>
              </Box>
            </CardContent>
          </Card>
        </>
      ) : null}
    </Box>
  );
}

export default function CollectionDetailPage() {
  return (
    <AuthGuard>
      <CollectionDetailContent />
    </AuthGuard>
  );
}

import { Box } from '@mui/material';
import CollectionCard from './CollectionCard';
import type { Collection } from '../../api/collections';

interface CollectionListProps {
  collections: Collection[];
  onEdit: (collection: Collection) => void;
  onDelete: (collection: Collection) => void;
  onClick: (collection: Collection) => void;
}

export default function CollectionList({
  collections,
  onEdit,
  onDelete,
  onClick,
}: CollectionListProps) {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
      {collections.map((collection) => (
        <CollectionCard
          key={collection.id}
          collection={collection}
          onEdit={() => onEdit(collection)}
          onDelete={() => onDelete(collection)}
          onClick={() => onClick(collection)}
        />
      ))}
    </Box>
  );
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors({ origin: 'http://localhost:3000' });
  await app.listen(process.env.PORT ?? 8080);
}
void bootstrap();

import {
  BadRequestException,
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Patch,
  Post,
  Put,
  Query,
  Req,
  UseGuards,
} from '@nestjs/common';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import type { RequestWithUser } from '../auth/jwt.strategy';
import { CollectionsService } from './collections.service';
import { CreateCollectionDto } from './dto/create-collection.dto';
import { UpdateCollectionDto } from './dto/update-collection.dto';
import { PatchCollectionDto } from './dto/patch-collection.dto';
import { QueryCollectionsDto } from './dto/query-collections.dto';
import type { CollectionResponse } from './dto/collection.response';
import type { Collection } from '../../generated/prisma/client';

@Controller('collections')
@UseGuards(JwtAuthGuard)
export class CollectionsController {
  constructor(private readonly collectionsService: CollectionsService) {}

  @Post()
  async create(
    @Req() req: RequestWithUser,
    @Body() dto: CreateCollectionDto,
  ): Promise<Collection> {
    return this.collectionsService.create(req.user.sub, dto);
  }

  @Get()
  async findAll(
    @Req() req: RequestWithUser,
    @Query() query: QueryCollectionsDto,
  ): Promise<CollectionResponse[]> {
    return this.collectionsService.findAll(req.user.sub, query);
  }

  @Get(':id')
  async findOne(
    @Req() req: RequestWithUser,
    @Param('id') id: string,
  ): Promise<CollectionResponse> {
    return this.collectionsService.findOne(id, req.user.sub);
  }

  @Put(':id')
  async update(
    @Req() req: RequestWithUser,
    @Param('id') id: string,
    @Body() dto: UpdateCollectionDto,
  ): Promise<Collection> {
    return this.collectionsService.update(id, req.user.sub, dto);
  }

  @Patch(':id')
  async patch(
    @Req() req: RequestWithUser,
    @Param('id') id: string,
    @Body() dto: PatchCollectionDto,
  ): Promise<Collection> {
    // Reject empty body — at least one field must be present
    if (dto.name === undefined) {
      throw new BadRequestException('At least one field must be provided');
    }
    return this.collectionsService.patch(id, req.user.sub, dto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  async delete(
    @Req() req: RequestWithUser,
    @Param('id') id: string,
  ): Promise<void> {
    await this.collectionsService.delete(id, req.user.sub);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import type { Collection } from '../../generated/prisma/client';
import type { CreateCollectionDto } from './dto/create-collection.dto';
import type { UpdateCollectionDto } from './dto/update-collection.dto';
import type { PatchCollectionDto } from './dto/patch-collection.dto';
import type { QueryCollectionsDto } from './dto/query-collections.dto';
import type { CollectionResponse } from './dto/collection.response';

/** Allowed sort columns */
type SortableColumn = 'name' | 'createdAt' | 'updatedAt';

/** Sort direction */
type SortOrder = 'asc' | 'desc';

@Injectable()
export class CollectionsService {
  constructor(private readonly prisma: PrismaService) {}

  /** Create a new collection for the given owner. */
  async create(ownerId: string, dto: CreateCollectionDto): Promise<Collection> {
    return this.prisma.collection.create({
      data: {
        name: dto.name,
        ownerId,
      },
    });
  }

  /** List collections for the given owner with optional filters and sorting. */
  async findAll(
    ownerId: string,
    query: QueryCollectionsDto,
  ): Promise<CollectionResponse[]> {
    const where: Record<string, unknown> = { ownerId };

    if (query.name) {
      where.name = { contains: query.name, mode: 'insensitive' };
    }

    const orderBy = this.buildOrderBy(query.sortBy, query.sortOrder);

    return this.prisma.collection.findMany({
      where,
      orderBy,
      include: { _count: { select: { bookmarks: true } } },
    });
  }

  /** Find a single collection by id, scoped to ownerId. */
  async findOne(id: string, ownerId: string): Promise<CollectionResponse> {
    const collection = await this.prisma.collection.findUnique({
      where: { id, ownerId },
      include: { _count: { select: { bookmarks: true } } },
    });

    if (!collection) {
      throw new NotFoundException('Collection not found');
    }

    return collection;
  }

  /** Fully replace a collection (PUT). */
  async update(
    id: string,
    ownerId: string,
    dto: UpdateCollectionDto,
  ): Promise<Collection> {
    await this.ensureOwnership(id, ownerId);

    return this.prisma.collection.update({
      where: { id, ownerId },
      data: { name: dto.name },
    });
  }

  /** Partially update a collection (PATCH). */
  async patch(
    id: string,
    ownerId: string,
    dto: PatchCollectionDto,
  ): Promise<Collection> {
    await this.ensureOwnership(id, ownerId);

    const data: Record<string, string> = {};
    if (dto.name !== undefined) {
      data.name = dto.name;
    }

    return this.prisma.collection.update({
      where: { id, ownerId },
      data,
    });
  }

  /** Delete a collection — disassociate bookmarks first, then delete in a transaction. */
  async delete(id: string, ownerId: string): Promise<void> {
    await this.ensureOwnership(id, ownerId);

    await this.prisma.$transaction([
      this.prisma.bookmark.updateMany({
        where: { collectionId: id, ownerId },
        data: { collectionId: null },
      }),
      this.prisma.collection.delete({
        where: { id, ownerId },
      }),
    ]);
  }

  // --- Private helpers ---

  /** Verify a collection exists and belongs to ownerId. Throws 404 otherwise. */
  private async ensureOwnership(id: string, ownerId: string): Promise<void> {
    const collection = await this.prisma.collection.findUnique({
      where: { id, ownerId },
    });

    if (!collection) {
      throw new NotFoundException('Collection not found');
    }
  }

  /** Build orderBy clause from sort parameters with safe defaults. */
  private buildOrderBy(
    sortBy?: string,
    sortOrder?: string,
  ): Record<string, SortOrder> {
    const column: SortableColumn =
      sortBy === 'name' || sortBy === 'updatedAt' ? sortBy : 'createdAt';
    const order: SortOrder = sortOrder === 'asc' ? 'asc' : 'desc';

    return { [column]: order };
  }
}

import {
  IsOptional,
  IsString,
  IsNotEmpty,
  MinLength,
  MaxLength,
} from 'class-validator';

export class PatchCollectionDto {
  @IsOptional()
  @IsString()
  @IsNotEmpty()
  @MinLength(1)
  @MaxLength(100)
  name?: string;
}

